// shell (v5.5): LAN room discovery -- the owner's listening port is random (PORT / :0), so another
// phone on the same Wi-Fi cannot find it by sweeping ports. Discovery is therefore pinned to one
// well-known port (LAN_DISCOVERY_PORT below) and the real port is handed back in /lan/rooms.port.
// The two routes are READ-ONLY and gated on the socket peer being loopback/private (net.js
// isLocalIp): X-Forwarded-For / CF-Connecting-IP are never consulted, so a public request cannot
// masquerade as a LAN peer. A public peer and an unknown room code get the SAME 404 body -- the
// response never reveals whether a code exists (LAN-discoverable, not internet-enumerable).
const LAN_DISCOVERY_PORT = 32123;
const lanRoomView = (r) => ({
  code: r.code,
  name: (r.seats.find((s) => s && !s.isBot && !s.left) || {}).name || r.code,
  mode: r.mode,
  difficulty: r.difficulty,
  seats: r.seats.length,
  humans: r.activeHumans().length,
  inMatch: r.match != null,
});
const lanRooms = () => {
  const out = [];
  for (const r of lobby.rooms.values()) if (r.mode === 'coop') out.push(lanRoomView(r));
  return out;
};
const isLanPeer = (req) => isLocalIp(normalizeIp(req && req.socket && req.socket.remoteAddress));
const lanNotFound = (req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  sendJson(req, res, 404, { ok: false, error: 'not found' });
};
/** Serve GET /lan/rooms and GET /lan/room?code= -- true when the request was handled. */
const handleLanRoute = (req, res, parts) => {
  if (parts.rawPath !== '/lan/rooms' && parts.rawPath !== '/lan/room') return false;
  res.setHeader('Access-Control-Allow-Origin', '*');
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.setHeader('Allow', 'GET, HEAD');
    sendJson(req, res, 405, { ok: false, error: 'method not allowed' });
    return true;
  }
  if (!isLanPeer(req)) { lanNotFound(req, res); return true; }
  if (parts.rawPath === '/lan/rooms') {
    sendJson(req, res, 200, { ok: true, app: APP_VERSION, protocol: PROTOCOL_VERSION, port: actualPort, rooms: lanRooms() });
    return true;
  }
  const code = String(new URLSearchParams(parts.query).get('code') || '').toUpperCase();
  if (!/^[A-Z0-9]{4}$/.test(code)) { lanNotFound(req, res); return true; }
  const room = lobby.getRoom(code);
  if (!room) { lanNotFound(req, res); return true; }
  sendJson(req, res, 200, { ok: true, port: actualPort, ...lanRoomView(room) });
  return true;
};

